-- HHBA energy third collection, 100 additional distinct employer entities 201–300.
-- Group subsidiaries may share one parent recruitment platform, so candidate_url is intentionally NOT UNIQUE.
-- Each employer_display_name is unique within this batch; all URLs are unverified discovery hints.
-- This remains preview-only and must NOT be put into trusted employer registry.
CREATE TABLE IF NOT EXISTS hhba_library_energy_employer_candidates (
 id TEXT PRIMARY KEY,
 collection_sequence INTEGER NOT NULL UNIQUE CHECK (collection_sequence BETWEEN 201 AND 300),
 employer_display_name TEXT NOT NULL UNIQUE,
 candidate_url TEXT NOT NULL,
 section_id TEXT NOT NULL REFERENCES hhba_library_hall_sections(section_id),
 hall_id TEXT NOT NULL DEFAULT 'energy' CHECK(hall_id='energy'),
 entry_kind TEXT NOT NULL CHECK(entry_kind IN ('ATS','SHARED_ATS','CAREERS','GROUP_CAREERS','NOTICE','DISCOVERY')),
 parent_group TEXT NOT NULL,
 batch_id TEXT NOT NULL DEFAULT 'ENERGY_EMPLOYERS_201_300',
 source_status TEXT NOT NULL DEFAULT 'UNVERIFIED' CHECK(source_status IN ('UNVERIFIED','REJECTED','REVIEWED')),
 collected_at TEXT NOT NULL DEFAULT '2026-11-11'
);
CREATE INDEX IF NOT EXISTS idx_hhba_energy_employer_candidates_section ON hhba_library_energy_employer_candidates(section_id,source_status);
CREATE INDEX IF NOT EXISTS idx_hhba_energy_employer_candidates_parent ON hhba_library_energy_employer_candidates(parent_group,source_status);
CREATE INDEX IF NOT EXISTS idx_hhba_energy_employer_candidates_url ON hhba_library_energy_employer_candidates(candidate_url);
